var i=`0406-welsh-rarebit`;var n=`world-0406`;var o=`GB`;var r=`northern-europe`;var a=4;var s=21;var u={en:`Welsh Rarebit`,ua:`Валлійський рейрбіт`};var d={en:`A traditional dish from United Kingdom, centered on white bread, all-purpose flour, whole cow milk, cheddar cheese. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: білий хліб, пшеничне борошно універсальне, цільне коров'яче молоко, сир чедер. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`white-bread`,8,`slice`]]},{en:`Melt the fat, stir in flour and cook gently for about 5 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 5 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:5,i:[[`unsalted-butter`,35,`g`],[`all-purpose-flour`,30,`g`],[`whole-cow-milk`,130,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`cheddar-cheese`,240,`g`],[`dijon-mustard`,12,`g`],[`worcestershire-sauce`,15,`ml`]]},{en:`Roast in a preheated 190°C oven for about 6 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 6 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:6,i:[]}];var h={slug:i,id:n,country:`GB`,region:r,servings:4,minutes:21,title:u,text:d,steps:l};export{o as country,h as default,n as id,s as minutes,r as region,a as servings,i as slug,l as steps,d as text,u as title};